import operator
from robot.errors import ExecutionFailed
from ta5g_file_system import ta5g_file_system


class SyslogMessages:
    """
    Class for syslog messages analysis methods.
    """

    operators = {
        '>': operator.gt,
        '<': operator.lt,
        '<=': operator.le,
        '>=': operator.ge,
        '==': operator.eq,
        '!=': operator.ne,
    }

    def __init__(self, syslog_lib):
        self.syslog_lib = syslog_lib

    def verify_syslog_for_given_number_of_messages(self, regexp, number_of_messages, alias, log_dir, compare_operator):
        """
        Counts the occurrences of message in syslog file and compare with expected number
        (number should be equal to expected number).
        :param string regexp: Pattern used to find the message in the syslog file.
        :param integer number_of_messages: Number of messages to compare.
        :param string alias: Unique identifier for a certain syslog instance.
        :param string log_dir: Path to directory where syslog file should be stored.
        :param string compare_operator: Comparison operator.
        """
        actual_num_of_messages = self._get_actual_number_of_messages(regexp=regexp, alias=alias, log_dir=log_dir)
        if not self.operators[compare_operator](actual_num_of_messages, number_of_messages):
            raise ExecutionFailed(
                message='Number of messages {0} is not {2} to {1}'.format(
                    str(actual_num_of_messages), str(number_of_messages), compare_operator
                ),
                continue_on_failure=True,
            )

    def _get_actual_number_of_messages(self, regexp, alias, log_dir):
        """
        Returns number of found messages in syslog file.
        :param string regexp: Pattern used to find the message in the syslog file.
        :param string alias: Unique identifier for a certain syslog instance.
        :param string log_dir: Path to directory where syslog file should be stored.
        :return: integer actual_num_of_messages: Number of found messages.
        """
        log_directory = ta5g_file_system().set_log_directory(log_dir, keep_underscores=True)
        actual_num_of_messages = self.syslog_lib.count_syslog_messages(
            alias=alias, regexp=regexp, log_path=log_directory
        )
        return actual_num_of_messages
